// ListView's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/list_view.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// How the items are arranged (see ListViewView). Changing it drops the hot item and column and any revealed cut-off text. Throws std::invalid_argument for an unknown view.
template <typename Declaring>
struct ListViewViewCapability {
    PropertyCell<ListViewView, ListViewViewCapability<Declaring>> view{ListViewView::details};

    static void assign(ListViewViewCapability& capability, ListViewView incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.view), incoming);
        if (!capability.view.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.view));
    }
};

